package com.way2jobs.latest;
import com.way2jobs.dto.JobCardResponse; import com.way2jobs.mapper.JobMapper; import com.way2jobs.service.JobService; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/jobs") @RequiredArgsConstructor public class LatestJobController {private final JobService jobService; @GetMapping("/latest") public ResponseEntity<Page<JobCardResponse>> latest(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){Pageable p=PageRequest.of(Math.max(page,0),Math.max(size,1),Sort.by("createdAt").descending());return ResponseEntity.ok(jobService.getJobs(p).map(JobMapper::toJobCard));}}
